import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { OrderItem } from '../../src/entities/order-item.entity';
import { buildOrderItem } from '../factories/order-item.factory';
import { Order } from '../../src/entities/order.entity';
import { buildOrder } from '../factories/order.factory';

describe('OrderItem Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let orderId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const orderEntity = em.create(
      Order,
      buildOrder(),
    );
    await em.persistAndFlush(orderEntity);
    orderId = orderEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to Order', () => {
    it('persists order reference', async () => {
      const em = orm.em.fork();
      const data = buildOrderItem({ order: orderId });
      const saved = em.create(OrderItem, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['order']);
      expect(saved.order.id).toBe(orderId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildOrderItem({ order: orderId });
      const saved = em.create(OrderItem, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        OrderItem,
        { id: saved.id },
        { populate: ['order'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.order).toBeDefined();
      expect(loaded!.order.id).toBe(orderId);
    });

    it('rejects entity without required order', async () => {
      const em = orm.em.fork();
      const data = buildOrderItem({ order: undefined as unknown as string });
      const row = em.create(OrderItem, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
